# --- Helper Functions ---

def _resolve_path(path):
    """Resolves a relative or absolute path to an absolute, normalized path."""
    if path.startswith('/'):
        absolute_path = path
    else:
        absolute_path = os.path.join(_current_path, path)

    # Normalize path (handle .., ., multiple slashes)
    normalized_path = []
    for part in absolute_path.split('/'):
        if part == '' or part == '.':
            continue
        if part == '..':
            if normalized_path:
                normalized_path.pop()
        else:
            normalized_path.append(part)

    return '/' + '/'.join(normalized_path)

def _get_node(path):
    """Retrieves a node (file or directory) from the filesystem based on its absolute path."""
    parts = path.split('/')
    current_node = _filesystem

    for part in parts:
        if not part:  # Skip empty parts from leading/trailing slashes or //
            continue
        if part not in current_node:
            return None, None # Node not found
        current_node = current_node[part]

    # The last part is the actual node, but we also need its parent for modifications
    # If path is '/', then parts will be ['',''], current_node will be _filesystem['/']
    # If path is '/foo', parts will be ['','foo'], current_node will be _filesystem['/']['foo']
    # We need to return the parent and the node itself.

    if path == '/':
        return None, _filesystem['/'] # Root has no parent in this structure

    parent_path = os.path.dirname(path)
    parent_node = _get_node(parent_path)[1] # Get the parent directory

    if parent_node and os.path.basename(path) in parent_node:
        return parent_node, parent_node[os.path.basename(path)]
    return None, None # Should not happen if _resolve_path is correct and node exists


def _get_dir_contents(path):
    """Returns a dictionary of contents for a given directory path."""
    _, node = _get_node(path)
    if node and node.get('type') == 'dir':
        # Filter out metadata keys like 'type', 'permissions'
        return {k: v for k, v in node.items() if k not in ['type', 'permissions', 'owner', 'group', 'mtime']}
    return {}

def _update_mtime(path):
    """Updates the modification time for a given path and its parent directories."""
    current_path = path
    while current_path != '/':
        parent_node, node = _get_node(current_path)
        if node:
            node['mtime'] = datetime.datetime.now()
        else:
            break # Path might be invalid
        current_path = os.path.dirname(current_path)
    # Update root's mtime if path was '/'
    if path == '/':
        _filesystem['/']['mtime'] = datetime.datetime.now()


# --- Command Implementations ---

