def cmd_ls(args):
    """Lists directory contents."""
    global _current_path

    show_hidden = False
    long_format = False
    classify = False

    target_paths = []

    # Parse options
    i = 0
    while i < len(args):
        arg = args[i]
        if arg.startswith('-'):
            for char in arg[1:]:
                if char == 'a':
                    show_hidden = True
                elif char == 'l':
                    long_format = True
                elif char == 'F':
                    classify = True
                else:
                    return f"ls: invalid option -- '{char}'\nTry 'ls --help' for more information."
            i += 1
        else:
            target_paths.append(arg)
            i += 1

    if not target_paths:
        target_paths.append('.') # Default to current directory

    output_lines = []

    for path_arg in target_paths:
        resolved_path = _resolve_path(path_arg)
        parent, node = _get_node(resolved_path)

        if not node:
            output_lines.append(f"ls: cannot access '{path_arg}': No such file or directory")
            continue

        if node['type'] == 'file':
            # If target is a file, just list the file itself
            if long_format:
                output_lines.append(_format_long_entry(os.path.basename(resolved_path), node, classify))
            else:
                output_lines.append(os.path.basename(resolved_path) + ("/" if classify and node['type'] == 'dir' else ""))
            continue

        # If target is a directory
        if len(target_paths) > 1:
            output_lines.append(f"{path_arg}:") # Header for multiple directories

        contents = _get_dir_contents(resolved_path)

        items = []
        if show_hidden:
            items.append({
                'name': '.',
                'node': node
            })
            if parent: # Only if not root
                 items.append({
                    'name': '..',
                    'node': parent
                })

        for name, sub_node in contents.items():
            if not show_hidden and name.startswith('.'):
                continue
            items.append({
                'name': name,
                'node': sub_node
            })

        items.sort(key=lambda x: x['name'].lower()) # Sort alphabetically

        if long_format:
            # Calculate total blocks (simplified)
            total_blocks = sum(
                (len(item['node'].get('content', '')) // 1024) + 1 # 1 block per KB or part of
                for item in items if item['node']['type'] == 'file'
            )
            # Add a block for each directory, including . and ..
            total_blocks += sum(1 for item in items if item['node']['type'] == 'dir')

            output_lines.append(f"total {total_blocks}")
            for item in items:
                output_lines.append(_format_long_entry(item['name'], item['node'], classify))
        else:
            # Simple list, multiple columns if possible (simplified to single column here)
            for item in items:
                display_name = item['name']
                if classify:
                    if item['node']['type'] == 'dir':
                        display_name += '/'
                    # Add other classifiers if needed (e.g., * for executables)
                output_lines.append(display_name)

        if len(target_paths) > 1 and path_arg != target_paths[-1]:
            output_lines.append("") # Blank line between directory listings

    return "\n".join(output_lines)

def _format_long_entry(name, node, classify=False):
    """Helper to format a single entry for ls -l output."""
    permissions = node.get('permissions', '---------')
    owner = node.get('owner', 'root')
    group = node.get('group', 'root')
    size = len(node.get('content', '')) if node['type'] == 'file' else 4096 # Directories often show 4096 bytes
    mtime = node.get('mtime', datetime.datetime.now())

    # Link count (simplified)
    nlink = 1
    if node['type'] == 'dir':
        # A directory has at least 2 links (itself and ..), plus one for each subdirectory
        # For simplicity, we'll just say 2 for files, 2 for empty dirs, or 3+ for dirs with subdirs
        nlink = 2 # . and ..
        if name != '.' and name != '..':
            # Count subdirectories for a more accurate nlink if this is a real dir
            nlink += sum(1 for k, v in node.items() if v.get('type') == 'dir' and k not in ['type', 'permissions', 'owner', 'group', 'mtime'])


    time_str = mtime.strftime("%b %d %H:%M") # e.g., Jan 01 12:34

    display_name = name
    if classify:
        if node['type'] == 'dir':
            display_name += '/'
        # Add other classifiers if needed (e.g., * for executables)

    return f"{permissions} {nlink} {owner} {group} {size:>8} {time_str} {display_name}"

def cmd_cd(args):
    """Changes the current working directory."""
    global _current_path

    target_path = args[0] if args else _users[_current_user]['home'] # Default to home

    resolved_path = _resolve_path(target_path)
    _, node = _get_node(resolved_path)

    if not node:
        return f"cd: {target_path}: No such file or directory"
    if node.get('type') != 'dir':
        return f"cd: {target_path}: Not a directory"

    _current_path = resolved_path
    return ""

def cmd_echo(args, redirect_to=None, append_to=None):
    """Prints arguments to stdout or redirects to a file."""
    output_content = " ".join(args)

    if redirect_to:
        resolved_path = _resolve_path(redirect_to)
        parent, node = _get_node(resolved_path)

        if not parent:
            return f"bash: {redirect_to}: No such file or directory" # Parent dir doesn't exist

        filename = os.path.basename(resolved_path)

        if filename in parent and parent[filename]['type'] == 'dir':
            return f"bash: {redirect_to}: Is a directory"

        if append_to:
            # Append to file
            if filename in parent and parent[filename]['type'] == 'file':
                parent[filename]['content'] += output_content + "\n"
            else: # Create new file
                parent[filename] = {'type': 'file', 'content': output_content + "\n", 'permissions': '-rw-r--r--', 'owner': _current_user, 'group': _current_user, 'mtime': datetime.datetime.now()}
        else:
            # Overwrite file
            parent[filename] = {'type': 'file', 'content': output_content + "\n", 'permissions': '-rw-r--r--', 'owner': _current_user, 'group': _current_user, 'mtime': datetime.datetime.now()}
        _update_mtime(resolved_path)
        _update_mtime(os.path.dirname(resolved_path)) # Update parent's mtime too
        return ""
    else:
        return output_content

def cmd_cat(args):
    """Concatenates and prints file contents."""
    if not args:
        return "cat: missing operand\nTry 'cat --help' for more information."

    output_lines = []
    for path_arg in args:
        resolved_path = _resolve_path(path_arg)
        _, node = _get_node(resolved_path)

        if not node:
            output_lines.append(f"cat: {path_arg}: No such file or directory")
        elif node['type'] == 'dir':
            output_lines.append(f"cat: {path_arg}: Is a directory")
        else:
            output_lines.append(node.get('content', ''))

    return "\n".join(output_lines)

def cmd_mkdir(args):
    """Creates new directories."""
    if not args:
        return "mkdir: missing operand\nTry 'mkdir --help' for more information."

    output_lines = []
    make_parents = False

    i = 0
    while i < len(args):
        arg = args[i]
        if arg == '-p':
            make_parents = True
            i += 1
        elif arg.startswith('-'):
            return f"mkdir: invalid option -- '{arg[1]}'\nTry 'mkdir --help' for more information."
        else:
            break

    target_dirs = args[i:]

    for dir_path in target_dirs:
        resolved_path = _resolve_path(dir_path)

        parts = resolved_path.split('/')
        current_node = _filesystem['/'] # Start from root
        current_abs_path = '/'

        for i, part in enumerate(parts):
            if not part: continue # Skip empty parts (e.g., from leading /)

            next_abs_path = os.path.join(current_abs_path, part)

            if part not in current_node:
                if current_node['type'] == 'file':
                    output_lines.append(f"mkdir: cannot create directory '{dir_path}': Not a directory (parent is a file)")
                    break # Cannot create directory if parent is a file

                if make_parents or i == len(parts) - 1: # Create if -p or it's the last part
                    current_node[part] = {'type': 'dir', 'permissions': 'drwxr-xr-x', 'owner': _current_user, 'group': _current_user, 'mtime': datetime.datetime.now()}
                    current_node = current_node[part]
                    _update_mtime(next_abs_path)
                    _update_mtime(current_abs_path) # Update parent
                else:
                    output_lines.append(f"mkdir: cannot create directory '{dir_path}': No such file or directory")
                    break
            else:
                if current_node[part]['type'] == 'file':
                    output_lines.append(f"mkdir: cannot create directory '{dir_path}': File exists (is a file)")
                    break
                if i == len(parts) - 1: # Trying to create existing directory
                    output_lines.append(f"mkdir: cannot create directory '{dir_path}': File exists")
                    break
                current_node = current_node[part]
            current_abs_path = next_abs_path

    return "\n".join(output_lines)

def cmd_rm(args):
    """Removes files or directories."""
    if not args:
        return "rm: missing operand\nTry 'rm --help' for more information."

    force = False
    recursive = False

    i = 0
    while i < len(args):
        arg = args[i]
        if arg.startswith('-'):
            for char in arg[1:]:
                if char == 'f':
                    force = True
                elif char == 'r' or char == 'R':
                    recursive = True
                else:
                    return f"rm: invalid option -- '{char}'\nTry 'rm --help' for more information."
            i += 1
        else:
            break

    target_paths = args[i:]
    output_lines = []

    for path_arg in target_paths:
        resolved_path = _resolve_path(path_arg)
        parent, node = _get_node(resolved_path)

        if not node:
            if not force:
                output_lines.append(f"rm: cannot remove '{path_arg}': No such file or directory")
            continue

        if resolved_path == '/':
            output_lines.append(f"rm: it is dangerous to operate recursively on '/'\nrm: use --no-preserve-root to override this failsafe")
            continue

        if node['type'] == 'dir':
            if not recursive:
                output_lines.append(f"rm: cannot remove '{path_arg}': Is a directory")
                continue

            # Check if directory is empty (excluding metadata keys)
            dir_contents = _get_dir_contents(resolved_path)
            if dir_contents and not force:
                output_lines.append(f"rm: cannot remove '{path_arg}': Directory not empty")
                continue

        # Perform removal
        if parent:
            del parent[os.path.basename(resolved_path)]
            _update_mtime(os.path.dirname(resolved_path)) # Update parent's mtime
        else: # Attempting to remove root itself (already caught by resolved_path == '/')
            output_lines.append(f"rm: cannot remove '{path_arg}': Operation not permitted")

    return "\n".join(output_lines)

def cmd_touch(args):
    """Updates the access and modification times of files, or creates them if they don't exist."""
    if not args:
        return "touch: missing file operand\nTry 'touch --help' for more information."

    output_lines = []
    for path_arg in args:
        resolved_path = _resolve_path(path_arg)
        parent, node = _get_node(resolved_path)

        if not parent: # Parent directory does not exist
            output_lines.append(f"touch: cannot touch '{path_arg}': No such file or directory")
            continue

        if node: # File/directory exists, just update mtime
            node['mtime'] = datetime.datetime.now()
        else: # Create new file
            filename = os.path.basename(resolved_path)
            parent[filename] = {'type': 'file', 'content': '', 'permissions': '-rw-r--r--', 'owner': _current_user, 'group': _current_user, 'mtime': datetime.datetime.now()}

        _update_mtime(resolved_path)
        _update_mtime(os.path.dirname(resolved_path)) # Update parent's mtime

    return "\n".join(output_lines)

def cmd_mv(args):
    """Moves or renames files or directories."""
    if len(args) < 2:
        return "mv: missing file operand\nTry 'mv --help' for more information."

    source_paths = args[:-1]
    destination_path = args[-1]

    output_lines = []

    for source_arg in source_paths:
        resolved_source = _resolve_path(source_arg)
        source_parent, source_node = _get_node(resolved_source)

        if not source_node:
            output_lines.append(f"mv: cannot stat '{source_arg}': No such file or directory")
            continue

        resolved_destination = _resolve_path(destination_path)
        dest_parent, dest_node = _get_node(resolved_destination)

        # Case 1: Destination is an existing directory
        if dest_node and dest_node['type'] == 'dir':
            new_name = os.path.basename(resolved_source)
            final_dest_path = os.path.join(resolved_destination, new_name)
            final_dest_parent, final_dest_node = _get_node(final_dest_path)

            if final_dest_node: # Item with same name exists in destination directory
                output_lines.append(f"mv: cannot move '{source_arg}' to '{destination_path}/{new_name}': File exists")
                continue

            source_parent.pop(os.path.basename(resolved_source))
            dest_node[new_name] = source_node
            _update_mtime(resolved_destination)
            _update_mtime(os.path.dirname(resolved_source))

        # Case 2: Destination does not exist, or is a file (rename)
        else:
            dest_filename = os.path.basename(resolved_destination)

            if not dest_parent: # Destination's parent does not exist
                output_lines.append(f"mv: cannot move to '{destination_path}': No such file or directory")
                continue

            if dest_parent[dest_filename] and dest_parent[dest_filename]['type'] == 'dir': # This should be caught by Case 1
                 output_lines.append(f"mv: cannot overwrite directory '{destination_path}' with non-directory '{source_arg}'")
                 continue

            # Rename or overwrite file
            source_parent.pop(os.path.basename(resolved_source))
            dest_parent[dest_filename] = source_node
            _update_mtime(resolved_destination)
            _update_mtime(os.path.dirname(resolved_source))
            _update_mtime(os.path.dirname(resolved_destination))

    return "\n".join(output_lines)

def cmd_cp(args):
    """Copies files or directories."""
    if len(args) < 2:
        return "cp: missing file operand\nTry 'cp --help' for more information."

    recursive = False

    i = 0
    while i < len(args):
        arg = args[i]
        if arg.startswith('-'):
            for char in arg[1:]:
                if char == 'r' or char == 'R':
                    recursive = True
                else:
                    return f"cp: invalid option -- '{char}'\nTry 'cp --help' for more information."
            i += 1
        else:
            break

    source_paths = args[i:-1]
    destination_path = args[-1]

    output_lines = []

    for source_arg in source_paths:
        resolved_source = _resolve_path(source_arg)
        source_parent, source_node = _get_node(resolved_source)

        if not source_node:
            output_lines.append(f"cp: cannot stat '{source_arg}': No such file or directory")
            continue

        if source_node['type'] == 'dir' and not recursive:
            output_lines.append(f"cp: -r not specified; omitting directory '{source_arg}'")
            continue

        resolved_destination = _resolve_path(destination_path)
        dest_parent, dest_node = _get_node(resolved_destination)

        target_parent_node = None
        target_name = None

        if dest_node and dest_node['type'] == 'dir':
            # Destination is an existing directory, copy into it
            target_parent_node = dest_node
            target_name = os.path.basename(resolved_source)
        elif dest_parent:
            # Destination is a non-existent path or an existing file (rename/overwrite)
            target_parent_node = dest_parent
            target_name = os.path.basename(resolved_destination)
        else: # Destination's parent doesn't exist
            output_lines.append(f"cp: cannot create regular file '{destination_path}': No such file or directory")
            continue

        if target_parent_node and target_name in target_parent_node and target_parent_node[target_name]['type'] == 'dir' and source_node['type'] == 'file':
            output_lines.append(f"cp: cannot overwrite directory '{destination_path}' with non-directory '{source_arg}'")
            continue

        # Perform the copy (deep copy for directories)
        new_node = _deep_copy_node(source_node)
        target_parent_node[target_name] = new_node
        new_node['mtime'] = datetime.datetime.now() # New timestamp for the copy

        _update_mtime(resolved_destination) # Update destination's mtime (or its parent's)

    return "\n".join(output_lines)

def _deep_copy_node(node):
    """Recursively copies a node and its contents (for cp -r)."""
    new_node = {k: v for k, v in node.items() if k not in ['type', 'content', 'permissions', 'owner', 'group', 'mtime']}
    new_node['type'] = node['type']
    new_node['permissions'] = node['permissions']
    new_node['owner'] = _current_user
    new_node['group'] = _current_user
    new_node['mtime'] = datetime.datetime.now()

    if node['type'] == 'file':
        new_node['content'] = node['content']
    elif node['type'] == 'dir':
        for name, sub_node in node.items():
            if name not in ['type', 'permissions', 'owner', 'group', 'mtime']:
                new_node[name] = _deep_copy_node(sub_node)
    return new_node


