def cmd_userdel(args):
    """Simulates userdel."""
    if not args:
        return "userdel: usage: userdel [options] LOGIN\n"
    username = args[0]
    if username not in _users:
        return f"userdel: user '{username}' does not exist\n"
    if username == "root":
        return "userdel: cannot remove the root account\n"

    remove_home = False

    i = 0
    while i < len(args):
        arg = args[i]
        if arg == '-r':
            remove_home = True
            i += 1
        elif arg.startswith('-'):
            return f"userdel: invalid option -- '{arg[1]}'\nTry 'userdel --help' for more information."
        else:
            break

    target_username = args[i]
    if target_username not in _users:
        return f"userdel: user '{target_username}' does not exist\n"

    home_dir = _users[target_username]['home']
    del _users[target_username]
    if target_username in _groups:
        del _groups[target_username]

    # Remove from /etc/passwd and /etc/shadow
    passwd_node = _get_node('/etc/passwd')[1]
    passwd_node['content'] = "\n".join([line for line in passwd_node['content'].splitlines() if not line.startswith(f"{target_username}:")]) + "\n"
    shadow_node = _get_node('/etc/shadow')[1]
    shadow_node['content'] = "\n".join([line for line in shadow_node['content'].splitlines() if not line.startswith(f"{target_username}:")]) + "\n"

