            output_lines.append(f"chmod: cannot access '{path_arg}': No such file or directory")
            continue

        # Simplified: just replace the permission string, no actual parsing/validation
        # In a real system, this would involve parsing octal or symbolic modes

        # Determine prefix 'd' for directories or '-' for files
        prefix = 'd' if node['type'] == 'dir' else '-'

        if re.fullmatch(r'[0-7]{3}', mode_str): # Octal mode (e.g., 755)
            # Convert octal to rwx string (simplified)
