                rwx_map = {'0': '---', '1': '--x', '2': '-w-', '3': '-wx',
                           '4': 'r--', '5': 'r-x', '6': 'rw-', '7': 'rwx'}
                return ''.join(rwx_map[c] for c in octal)

            user_perm = octal_to_rwx(mode_str[0])
            group_perm = octal_to_rwx(mode_str[1])
            other_perm = octal_to_rwx(mode_str[2])

            node['permissions'] = f"{prefix}{user_perm}{group_perm}{other_perm}"
            output_lines.append(f"chmod: changing permissions of '{path_arg}' to {mode_str} (simplified)")
        else:
            output_lines.append(f"chmod: invalid mode: '{mode_str}' (only octal modes like 755 are fully supported in this simulation)")

