        output = cmd_history()
    elif cmd == "apt":
        if len(args) > 0 and args[0] == "update":
            output = cmd_apt_update()
        elif len(args) > 0 and args[0] == "install":
            output = cmd_apt_install(args[1:])
        else:
            output = "apt: unrecognized command or option\n"
    elif cmd == "useradd":
        output = cmd_useradd(args)
    elif cmd == "userdel":
        output = cmd_userdel(args)
    elif cmd == "passwd":
        output = cmd_passwd(args)
    elif cmd == "chmod":
